import unittest
from latency import percentile

class Latency(unittest.TestCase):
    def test_ranks_and_copy(self):
        source = [91, 7, 40, 18]
        for q, expected in [(0.01,7),(0.25,7),(0.5,18),(0.75,40),(1,91)]:
            self.assertEqual(percentile(source,q),expected)
        self.assertEqual(source,[91,7,40,18])
        self.assertEqual(percentile(list(range(1,101)),0.14),14)
        self.assertEqual(percentile((x for x in [8,2,5]),0.5),5)
        self.assertEqual(percentile([19],1),19)
    def test_bad_inputs(self):
        for q in [0,-0.2,1.1,float('nan')]:
            with self.assertRaises(ValueError): percentile([3],q)
        with self.assertRaises(ValueError): percentile([],0.5)

if __name__ == '__main__':
    unittest.main()

