import math
from fractions import Fraction

def percentile(samples, q):
    if not 0 < q <= 1:
        raise ValueError('q outside range')
    values = sorted(samples)
    if not values:
        raise ValueError('no samples')
    return values[math.ceil(Fraction(str(q)) * len(values)) - 1]

